#include <iostream>
using namespace std;

int main() {
    long long n;
    cin >> n;

    const char* names[] = {"Sheldon", "Leonard", "Penny", "Rajesh", "Howard"};
    long long repetitions = 1;

    while (n > 5 * repetitions) {
        n -= 5 * repetitions;
        repetitions *= 2;
    }

    cout << names[(n - 1) / repetitions] << '\n';
    return 0;
}

